# -*- coding: utf-8 -*-
"""节点文字（续）：前200 年以后。"""

TEXT2 = {
    "h200": dict(era="高帝七年", era_en="Emperor Gaozu, year 7", t="白登之围·和亲", te="Siege of Baideng · heqin", sh="白登之围", she="Baideng",
                 d="冒顿东灭东胡、西走月氏，南并楼烦、白羊河南王，北服浑庾、屈射、丁零、鬲昆、薪犁，尽收蒙恬所夺地。高祖疑忌功臣：燕王臧荼反被诛，以卢绾为燕王；"
                   "楚王韩信被擒于陈，楚分为荆、楚；立长子刘肥为齐王。韩王信徙太原、都马邑，降匈奴。七年高祖亲征，被围于白登七日，用陈平计得脱，"
                   "此后与匈奴和亲。",
                 de="Modu destroyed the Donghu to the east, drove off the Yuezhi to the west, absorbed the Loufan and Baiyang kings of the Ordos to the south "
                    "and subdued the Hunyu, Qushe, Dingling, Gekun and Xinli to the north, taking back all the land Meng Tian had seized. Gaozu grew wary of "
                    "his generals: Zang Tu, king of Yan, rebelled and was killed, Lu Wan replacing him; Han Xin, king of Chu, was seized at Chen and Chu split "
                    "into Jing and Chu; Gaozu's eldest son Liu Fei became king of Qi. Han Xin, king of Han (韓), was moved to Taiyuan with his capital at Mayi and "
                    "went over to the Xiongnu. In year 7 Gaozu led an army himself and was surrounded at Baideng for seven days, escaping by a stratagem of "
                    "Chen Ping; thereafter Han made peace with the Xiongnu through marriage alliances (heqin)."),
    "h195": dict(era="高帝十二年", era_en="Emperor Gaozu, year 12", t="高祖崩·同姓诸王", te="Death of Gaozu · kings of the Liu clan", sh="同姓王", she="Liu kings",
                 d="异姓诸王相继覆灭：赵王张敖废，梁王彭越、淮南王英布被诛，燕王卢绾亡入匈奴，惟长沙王吴氏得存。刘氏子弟分王关东：齐、楚、吴、淮南、梁、"
                   "淮阳、赵、代、燕，「非刘氏而王者，天下共击之」。王国大者跨州兼郡，汉廷直辖者仅十五郡。高祖遣陆贾立赵佗为南越王。四月高祖崩。",
                 de="The kings of other surnames fell one after another: Zhang Ao of Zhao was deposed, Peng Yue of Liang and Ying Bu of Huainan were executed "
                    "and Lu Wan of Yan fled to the Xiongnu; only the Wu family of Changsha survived. Sons and brothers of the Liu clan were made kings east of "
                    "the passes — Qi, Chu, Wu, Huainan, Liang, Huaiyang, Zhao, Dai and Yan — under the oath that 'if anyone not of the Liu clan becomes king, "
                    "let the realm unite to strike him'. The great kingdoms spanned many commanderies, while the court ruled only fifteen directly. Gaozu "
                    "sent Lu Jia to recognise Zhao Tuo as king of Nanyue, and died in the 4th month."),
    "h180": dict(era="高后八年", era_en="Empress Lü, year 8", t="诛诸吕·文帝即位", te="The Lü clan purged · Emperor Wen", sh="诛诸吕", she="Lü purge",
                 d="吕后临朝，封诸吕为王：吕禄为赵王，吕产为梁王，吕通为燕王，又割齐之济南为吕国、琅邪为琅邪国。前194 年燕人卫满逐朝鲜王准，建卫氏朝鲜；"
                   "南越赵佗与汉绝，自称南越武帝，发兵攻长沙，又并瓯雒。七月吕后崩，周勃、陈平诛诸吕，后九月迎代王刘恒即位，是为文帝。",
                 de="Empress Lü ruled from the court and made kings of her kinsmen — Lü Lu in Zhao, Lü Chan in Liang, Lü Tong in Yan — and carved the kingdoms of Lü (from Jinan) "
                    "and Langya out of Qi. In 194 BC Wiman of Yan had driven out King Jun of Joseon and founded Wiman Joseon; Zhao Tuo of Nanyue broke with Han, "
                    "styled himself Emperor Wu of Nanyue, attacked Changsha and annexed Âu Lạc. Empress Lü died in the 7th month; Zhou Bo and Chen Ping "
                    "wiped out the Lü clan and in the intercalary 9th month brought Liu Heng, king of Dai, to the throne as Emperor Wen."),
    "h164": dict(era="文帝十六年", era_en="Emperor Wen, year 16", t="齐分六国·淮南三分", te="Qi split into six · Huainan into three", sh="分齐", she="Qi divided",
                 d="贾谊上《治安策》，主张「众建诸侯而少其力」。文帝十六年分齐为齐、济北、济南、菑川、胶西、胶东六国（另有城阳），分淮南为淮南、衡山、庐江三国，"
                   "皆以故王子弟为王。前176 年冒顿单于击破月氏，老上单于又杀月氏王，月氏大部西迁伊犁；楼兰、乌孙、呼揭及其旁二十六国皆役属匈奴。",
                 de="Jia Yi argued in his Memorial on Order and Security for 'setting up many lords to lessen their strength'. In Emperor Wen's 16th year Qi "
                    "was divided into the six kingdoms of Qi, Jibei, Jinan, Zichuan, Jiaoxi and Jiaodong (besides Chengyang), and Huainan into Huainan, "
                    "Hengshan and Lujiang, all given to sons of the former kings. The chanyu Modu had crushed the Yuezhi in 176 BC, and after the chanyu Laoshang killed their king most of them moved west "
                    "to the Ili valley; Loulan, Wusun, Hujie and twenty-six neighbouring states all became subject to the Xiongnu."),
    "h154": dict(era="景帝三年", era_en="Emperor Jing, year 3", t="七国之乱", te="Rebellion of the Seven States", sh="七国乱", she="Seven States",
                 d="晁错上《削藩策》，削楚之东海、赵之常山、胶西六县。正月吴王刘濞联合楚、赵、胶西、胶东、菑川、济南起兵，以「诛晁错，清君侧」为名。"
                   "景帝斩晁错，遣周亚夫坚壁昌邑，以轻骑断吴楚粮道，梁王坚守睢阳；三月吴楚溃，刘濞走东越被杀，七国皆平。此后王国不得自治民补吏，"
                   "汉廷收其支郡，王国渐同于郡。",
                 de="Chao Cuo memorialised for cutting down the kingdoms, and Donghai was taken from Chu, Changshan from Zhao and six counties from Jiaoxi. In "
                    "the 1st month Liu Bi, king of Wu, rose with Chu, Zhao, Jiaoxi, Jiaodong, Zichuan and Jinan, claiming to 'execute Chao Cuo and purge the "
                    "emperor's side'. Emperor Jing had Chao Cuo beheaded and sent Zhou Yafu, who dug in at Changyi and cut the Wu–Chu supply lines with light "
                    "cavalry while the king of Liang held Suiyang; in the 3rd month Wu and Chu collapsed, Liu Bi fled to Dongyue and was killed, and all seven "
                    "were crushed. Thereafter kings could no longer govern their people or appoint officials, the court took back their outlying commanderies "
                    "and the kingdoms became little different from commanderies."),
    "h138": dict(era="建元三年", era_en="Jianyuan 3", t="东瓯内徙·张骞西使", te="Dong'ou moves inland · Zhang Qian goes west", sh="东瓯内徙", she="Dong'ou",
                 d="武帝即位，前139 年前后遣张骞以郎应募，出陇西往使大月氏，欲共击匈奴，途中为匈奴所留十余年。闽越发兵围东瓯，东瓯告急，严助发会稽兵浮海往救，"
                   "闽越引去；东瓯王请举国内徙，四万余人徙处江淮之间，其地空。",
                 de="Emperor Wu came to the throne, and around 139 BC Zhang Qian, a palace attendant who had volunteered, set out from Longxi as envoy to the "
                    "Great Yuezhi to seek an alliance against the Xiongnu; he was held by the Xiongnu on the way for more than ten years. Minyue besieged "
                    "Dong'ou; when Dong'ou appealed for help Yan Zhu brought the Kuaiji troops by sea and Minyue withdrew. The king of Dong'ou asked to move "
                    "his whole kingdom, and over forty thousand people were resettled between the Yangzi and the Huai, leaving the land empty."),
    "h127": dict(era="元朔二年", era_en="Yuanshuo 2", t="收河南·置朔方", te="The Ordos recovered · Shuofang", sh="收河南", she="Ordos",
                 d="前133 年马邑之谋不成，汉匈和亲断绝。元朔二年卫青出云中，西至高阙、陇西，击走白羊、楼烦王，尽收河南地，置朔方、五原郡，募民十万口徙朔方，"
                   "复缮蒙恬故塞。同年用主父偃之策行推恩令，诸侯王得分邑封子弟为列侯，王国由是愈小；齐国以齐王刘次昌自杀国除。前128 年濊君南闾降，置苍海郡。",
                 de="After the failed ambush at Mayi in 133 BC the peace between Han and the Xiongnu broke down. In Yuanshuo 2 Wei Qing struck out from Yunzhong "
                    "west to Gaoque and Longxi, drove off the Baiyang and Loufan kings and took back the whole of the Ordos; Shuofang and Wuyuan commanderies were "
                    "set up, a hundred thousand settlers recruited for Shuofang and Meng Tian's old frontier rebuilt. The same year, on Zhufu Yan's advice, the "
                    "Edict of Grace allowed kings to divide their lands among younger sons as marquisates, so the kingdoms grew ever smaller; Qi was abolished "
                    "when its king, Liu Cichang, killed himself. In 128 BC the Ye chief Namnyeo had submitted and Canghai Commandery had been set up."),
    "h121": dict(era="元狩二年", era_en="Yuanshou 2", t="河西之战", te="The Hexi campaign", sh="河西之战", she="Hexi",
                 d="霍去病春出陇西，过焉支山千余里；夏出北地，逾居延，至祁连山，大破匈奴休屠、浑邪部。秋浑邪王杀休屠王，率四万余众降汉，汉分处五属国，"
                   "河西走廊尽为汉有，自金城河西并南山至盐泽空无匈奴；后陆续置酒泉、张掖、敦煌、武威四郡。前122 年淮南王刘安、衡山王刘赐谋反，二国除。",
                 de="Huo Qubing struck out from Longxi in spring, more than a thousand li past Mount Yanzhi, and in summer from Beidi past Juyan to the Qilian "
                    "Mountains, crushing the Xiutu and Hunye divisions of the Xiongnu. In autumn the Hunye king killed the Xiutu king and surrendered with over "
                    "40,000 people, who were settled in five dependent states. The whole Hexi Corridor became Han, and from Jincheng west along the Southern "
                    "Mountains to the Salt Marsh there were no more Xiongnu; the four commanderies of Jiuquan, Zhangye, Dunhuang and Wuwei were set up over the "
                    "following years. Liu An of Huainan and Liu Ci of Hengshan were found plotting rebellion in 122 BC and both kingdoms were abolished."),
    "h119": dict(era="元狩四年", era_en="Yuanshou 4", t="漠北之战", te="Battle beyond the Gobi", sh="漠北之战", she="Gobi",
                 d="卫青、霍去病各将五万骑，步兵转运者数十万，绝漠北击。卫青出定襄，与伊稚斜单于遇，单于溃围北走，汉军至窴颜山赵信城；霍去病出代郡二千余里，"
                   "破左贤王，封狼居胥山，禅于姑衍，临瀚海而还。「是后匈奴远遁，而幕南无王庭」。汉徙乌桓于五郡塞外，以护乌桓校尉监之。",
                 de="Wei Qing and Huo Qubing each led 50,000 horsemen, with hundreds of thousands of foot soldiers carrying supplies, across the Gobi. Wei Qing, "
                    "setting out from Dingxiang, met the chanyu Yizhixie, who broke through and fled north, and the Han army reached Zhao Xin's fort at Mount "
                    "Tianyan; Huo Qubing marched more than two thousand li from Dai, crushed the Wise King of the Left, sacrificed to Heaven on Mount Langjuxu "
                    "and to Earth on Mount Guyan, and turned back at the Hanhai. 'After this the Xiongnu fled far away, and there was no royal court south of "
                    "the desert.' Han moved the Wuhuan beyond the frontier of five commanderies under a Protector of the Wuhuan."),
    "h111": dict(era="元鼎六年", era_en="Yuanding 6", t="平南越·开西南夷", te="Nanyue conquered · the southwest opened", sh="平南越", she="Nanyue",
                 d="南越相吕嘉杀王及汉使，元鼎五年路博德、杨仆五路进兵，六年冬破番禺，以其地置南海、苍梧、郁林、合浦、交趾、九真、日南、珠崖、儋耳九郡。"
                   "回师平且兰，夜郎王入朝，以其地为牂柯郡，并置越嶲、沈黎、汶山、武都郡。同年李息击西羌，置护羌校尉；张骞二使西域已于前115 年归汉。",
                 de="Lü Jia, chancellor of Nanyue, killed his king and the Han envoys; in Yuanding 5 Lu Bode and Yang Pu advanced by five routes and in the winter "
                    "of year 6 took Panyu, making the land into the nine commanderies of Nanhai, Cangwu, Yulin, Hepu, Jiaozhi, Jiuzhen, Rinan, Zhuya and Dan'er. "
                    "On the way back the army destroyed Qielan; the king of Yelang came to court and his land became Zangke Commandery, while Yuexi, Shenli, "
                    "Wenshan and Wudu commanderies were also set up. That year Li Xi attacked the Western Qiang and a Protector of the Qiang was appointed; "
                    "Zhang Qian had returned from his second mission to the west in 115 BC."),
    "h108": dict(era="元封三年", era_en="Yuanfeng 3", t="平朝鲜·置四郡", te="Joseon conquered · four commanderies established", sh="四郡", she="4 commanderies",
                 d="前110 年汉灭闽越、东越，徙其民于江淮；前109 年滇王降，置益州郡。卫氏朝鲜右渠王阻真番诸国朝汉，杀辽东都尉涉何；楼船将军杨仆浮渤海、"
                   "左将军荀彘出辽东夹击，元封三年夏王险城降，以其地置乐浪、临屯、真番、玄菟四郡。赵破奴虏楼兰王、破车师，汉自酒泉列亭障至玉门。"
                   "至此武帝开边大体告成，郡国并行之局见于全图。",
                 de="In 110 BC Han destroyed Minyue and Dongyue and moved their peoples to the Yangzi–Huai region; in 109 BC the king of Dian surrendered and "
                    "Yizhou Commandery was set up. Ugeo, king of Wiman Joseon, blocked Zhenfan and other states from coming to the Han court and killed the "
                    "Liaodong commandant She He; Yang Pu, General of the Towered Ships, crossed the Bohai while General of the Left Xun Zhi came out of Liaodong, and "
                    "in the summer of Yuanfeng 3 Wangxian surrendered, the land becoming the four commanderies of Lelang, Lintun, Zhenfan and Xuantu. Zhao Ponu "
                    "captured the king of Loulan and broke Jushi, and Han built a line of watchtowers from Jiuquan to the Jade Gate. Emperor Wu's expansion "
                    "was now largely complete, and the whole map shows commanderies and kingdoms side by side."),
    "h101": dict(era="太初四年", era_en="Taichu 4", t="伐大宛", te="War against Dayuan", sh="伐大宛", she="Dayuan",
                 d="前104 年改用太初历，以正月为岁首。贰师将军李广利求汗血马，首伐大宛不利；太初三年再发兵六万，围贵山城四十余日，大宛贵人杀王毋寡，"
                   "献马三千余匹，汉立亲汉的昧蔡为王。「西域震惧」，汉自敦煌西至盐泽往往起亭，轮台、渠犁屯田数百人，置使者校尉。光禄勋徐自为筑五原塞外列城"
                   "（光禄塞），路博德筑居延泽上。",
                 de="In 104 BC the Taichu calendar was adopted, making the 1st month the start of the year. Li Guangli, the Ershi General, went for Dayuan's "
                    "'blood-sweating' horses; his first campaign failed, but in Taichu 3 he set out again with 60,000 men and besieged Guishan for over forty "
                    "days, until the Dayuan nobles killed their king Wugua, handed over more than three thousand horses, and Han installed the pro-Han Meicai as "
                    "king. 'The Western Regions shook with fear': Han built watch posts all the way west from Dunhuang to the Salt Marsh, settled several "
                    "hundred farming soldiers at Luntai and Quli under an envoy-commandant, while the Superintendent of the Palace Xu Ziwei built the chain of forts beyond Wuyuan (the Guanglu "
                    "frontier) and Lu Bode fortified Lake Juyan."),
    "h60": dict(era="神爵二年", era_en="Shenjue 2", t="置西域都护", te="Protectorate of the Western Regions founded", sh="西域都护", she="Protectorate",
                d="前87 年武帝崩，此前下轮台诏罢远戍，昭帝时盐铁会议论政、霍光辅政。前71 年汉发五将军十五万骑与乌孙夹击匈奴，匈奴自此衰耗。神爵二年匈奴日逐王"
                  "先贤掸率众降汉，郑吉迎之，汉以郑吉并护车师以西北道，号西域都护，治乌垒城，统领西域三十六国，「汉之号令班西域矣」。前61 年赵充国屯田湟中，"
                  "平西羌，置金城属国。",
                de="Emperor Wu died in 87 BC, having earlier issued the Luntai edict abandoning distant garrisons; under Emperor Zhao the Salt and Iron debate was "
                   "held and Huo Guang ruled as regent. In 71 BC Han sent five generals with 150,000 horsemen to attack the Xiongnu together with Wusun, and the "
                   "Xiongnu declined from then on. In Shenjue 2 the Xiongnu Rizhu king Xianxianshan came over to Han with his people; Zheng Ji went to receive him, "
                   "and was given charge of the northern route west of Jushi as well, with the title Protector-General of the Western Regions, based at Wulei "
                   "and overseeing the thirty-six states: 'the commands of Han were proclaimed throughout the Western Regions'. In 61 BC Zhao Chongguo set up "
                   "farming garrisons on the Huang River, subdued the Western Qiang and created the Jincheng Dependent State."),
    "h51": dict(era="甘露三年", era_en="Ganlu 3", t="呼韩邪入朝", te="Huhanye comes to court", sh="呼韩邪", she="Huhanye",
                d="前57 年匈奴五单于争立，后并为呼韩邪、郅支两部。呼韩邪为郅支所败，南下近塞，甘露三年正月亲朝宣帝于甘泉宫，称臣，位在诸侯王上，"
                  "汉遣兵护送其出居光禄塞下，转边谷米以济之。郅支据单于庭，旋西击乌揭、坚昆、丁零，徙居坚昆。前53 年乌孙分大小昆弥。",
                de="In 57 BC five chanyus contended for the Xiongnu throne, ending in two camps under Huhanye and Zhizhi. Defeated by Zhizhi, Huhanye moved south "
                   "close to the frontier, and in the 1st month of Ganlu 3 came in person to Emperor Xuan at the Ganquan Palace, declaring himself a vassal and "
                   "taking precedence above the kings of the realm; Han troops escorted him out to live below the Guanglu frontier and grain was sent from the "
                   "border commanderies to feed his people. Zhizhi held the chanyu's court, then struck west against the Wujie, Jiankun and Dingling and moved "
                   "to the Jiankun lands. In 53 BC Wusun was divided between a greater and a lesser kunmi."),
    "h36": dict(era="建昭三年", era_en="Jianzhao 3", t="陈汤斩郅支", te="Chen Tang kills Zhizhi", sh="斩郅支", she="Zhizhi",
                d="呼韩邪于前43 年北归单于庭，匈奴复归一统而称臣于汉。郅支杀汉使谷吉，西投康居，役使康居、筑城于都赖水上，威胁乌孙、大宛。建昭三年西域副校尉"
                  "陈汤矫制，与都护甘延寿发西域十五国兵及屯田吏士四万余人，分南北两道，南道越葱岭、经大宛，北道经乌孙，围郅支城，斩郅支单于，传首京师，上书曰「明犯强汉者，虽远必诛」。",
                de="Huhanye returned north to the chanyu's court in 43 BC, and the Xiongnu, reunited, remained a Han vassal. Zhizhi had killed the Han envoy Gu Ji "
                   "and gone west to Kangju, which he dominated, building a fortress on the Talas from which he threatened Wusun and Dayuan. In Jianzhao 3 the "
                   "Deputy Colonel of the Western Regions Chen Tang, forging an imperial order, joined the Protector-General Gan Yanshou in raising more than "
                   "40,000 men from fifteen states of the Western Regions and the farming garrisons; marching by two routes, the southern over the Pamirs through Dayuan and the northern through Wusun, they "
                   "besieged Zhizhi's fortress and beheaded the chanyu, sending his head to the capital with the memorial: 'whoever offends mighty Han, "
                   "however far away, shall be put to death'."),
    "x2": dict(era="元始二年", era_en="Yuanshi 2", t="元始郡国", te="The commanderies and kingdoms of Yuanshi", sh="元始", she="Yuanshi",
               d="前33 年王昭君出塞，嫁呼韩邪单于，汉匈和好六十余年。元始二年为《汉书·地理志》所据的断代：郡国一百零三，县邑一千三百一十四，道三十二，侯国二百四十一，"
                 "户一千二百二十三万，口五千九百五十九万，为西汉极盛。是时平帝年幼，大司马王莽秉政，号安汉公。西域都护领五十国。",
               de="In 33 BC Wang Zhaojun went out beyond the frontier to marry the chanyu Huhanye, and Han and the Xiongnu were at peace for over sixty years. Yuanshi 2 "
                  "is the benchmark year of the Han shu Treatise on Geography: 103 commanderies and kingdoms, 1,314 counties, 32 dao and 241 marquisates, "
                  "12.23 million households and 59.59 million people — the height of the Western Han. Emperor Ping was a child and Wang Mang, Grand Marshal, "
                  "ruled as Duke Who Secures the Han. The Protector-General oversaw fifty states."),
    "x9": dict(era="始建国元年", era_en="Shijianguo 1", t="王莽代汉", te="Wang Mang takes the throne", sh="王莽代汉", she="Wang Mang",
               d="初始元年十二月王莽受汉禅，建国号新，改元始建国，以十二月为正月。行王田、私属，五均六筦，改币制；诸侯王降为公，次年皆废；大改郡县名称与长吏官名。"
                 "又改匈奴单于玺为「新匈奴单于章」，贬句丽王为侯，西域诸国王为侯，四夷离心：匈奴寇边，13 年焉耆杀西域都护但钦，西域遂绝。",
               de="In the 12th month of Chushi 1 Wang Mang accepted the abdication of Han, naming his dynasty Xin and his era Shijianguo and making the 12th "
                  "month the 1st. He nationalised land and banned the sale of slaves, set up price controls and state monopolies and changed the coinage; kings "
                  "were reduced to dukes and abolished the following year, and the names of commanderies, counties and their officials were overhauled. He "
                  "replaced the Xiongnu chanyu's seal with one reading 'Seal of the Xin Xiongnu chanyu' and demoted the king of Goguryeo and the kings of the "
                  "Western Regions to marquises, alienating every neighbour: the Xiongnu raided the frontier, and in AD 13 Karasahr killed the Protector-General "
                  "Dan Qin, and contact with the Western Regions was cut off."),
    "x18": dict(era="天凤五年", era_en="Tianfeng 5", t="绿林赤眉", te="Lülin and the Red Eyebrows", sh="绿林赤眉", she="Lülin",
                d="连年旱蝗，河决魏郡（11 年）后黄河改道东流、河南北久成泽国，饥民四起。17 年王匡、王凤聚众于绿林山；18 年琅邪樊崇起于莒，转战青、徐，"
                  "以朱涂眉为号，称赤眉。王莽遣廉丹、太师王匡东击，不能制。",
                de="Year after year of drought and locusts, together with the Yellow River's breach at Wei Commandery in AD 11 — after which the river changed "
                   "course to the east and the lands north and south of it lay long under water — drove the starving to revolt. In 17 Wang Kuang and Wang "
                   "Feng gathered followers at Mount Lülin; in 18 Fan Chong of Langya rose at Ju and fought through Qing and Xu, his men painting their "
                   "eyebrows red: the Red Eyebrows. The armies Wang Mang sent east under Lian Dan and the Grand Preceptor Wang Kuang could not contain them."),
    "x23": dict(era="地皇四年", era_en="Dihuang 4", era2="更始元年", era2_en="Gengshi 1", t="昆阳之战·新亡", te="Kunyang · the fall of Xin",
                sh="昆阳之战", she="Kunyang",
                d="二月绿林诸将立刘玄为帝，年号更始。王莽遣王寻、王邑号称百万围昆阳，六月刘秀以三千敢死士冲其中坚，会大雷风，新军溃。邓晔、于匡开武关，"
                  "九月一日（戊申）汉兵攻入长安，三日（庚戌）王莽死于渐台。更始都洛阳，遣刘秀徇河北；隗嚣据陇右，公孙述据蜀，各自拥兵。",
                de="In the 2nd month the Lülin leaders set up Liu Xuan as emperor with the era name Gengshi. Wang Mang sent Wang Xun and Wang Yi with an army said "
                   "to number a million to besiege Kunyang; in the 6th month Liu Xiu charged their centre with three thousand picked men, a great storm broke, "
                   "and the Xin army fell apart. Deng Ye and Yu Kuang opened the Wu Pass, Han troops broke into Chang'an on the first day of the 9th month, and on the third "
                   "Wang Mang was killed at the Jian Terrace. The Gengshi Emperor made Luoyang his capital and sent Liu Xiu to win over Hebei; Wei Xiao held "
                   "Longyou and Gongsun Shu held Shu, each with his own army."),
    "d25": dict(era="建武元年", era_en="Jianwu 1", era2="龙兴元年（成家）", era2_en="Longxing 1 (Chengjia)", t="光武即位·赤眉入长安",
                te="Guangwu enthroned · the Red Eyebrows in Chang'an", sh="光武即位", she="Guangwu",
                d="刘秀平王郎、收铜马，据有河北，六月即皇帝位于鄗南千秋亭，十月入洛阳，定都，是为东汉。赤眉立刘盆子为帝，九月入长安，更始出降，旋被杀。"
                  "公孙述称帝于成都，国号成家；梁王刘永称帝于睢阳，张步据齐，董宪据东海，隗嚣据陇右，窦融保河西，秦丰、李宪等各据一方，天下分裂。",
                de="Liu Xiu crushed Wang Lang and absorbed the Tongma rebels, taking Hebei; in the 6th month he took the throne at the Qianqiu Pavilion south of "
                   "Hao, and in the 10th entered Luoyang and made it his capital: the Eastern Han had begun. The Red Eyebrows set up Liu Penzi as emperor and "
                   "entered Chang'an in the 9th month; the Gengshi Emperor surrendered and was soon killed. Gongsun Shu proclaimed himself emperor of Chengjia at Chengdu; "
                   "Liu Yong, king of Liang, did the same at Suiyang; Zhang Bu held Qi, Dong Xian Donghai, Wei Xiao Longyou and Dou Rong Hexi, while Qin Feng, "
                   "Li Xian and others held their own corners: the realm was in pieces."),
    "d27": dict(era="建武三年", era_en="Jianwu 3", t="赤眉降", te="The Red Eyebrows surrender", sh="赤眉降", she="Red Eyebrows",
                d="赤眉在关中掠食殆尽，东归。建武三年正月冯异破之于崤底，光武亲率大军截于宜阳，樊崇、刘盆子君臣面缚请降，关中渐定。刘永为部将所杀，其子刘纡继立；"
                  "渔阳太守彭宠反，自立为燕王。",
                de="Having stripped Guanzhong of food, the Red Eyebrows turned east. In the 1st month of Jianwu 3 Feng Yi beat them at Xiaodi, and the emperor "
                   "himself blocked their way at Yiyang, where Fan Chong and Liu Penzi surrendered with their hands bound; Guanzhong was gradually pacified. "
                   "Liu Yong was killed by one of his generals and his son Liu Yu took his place; Peng Chong, Administrator of Yuyang, rebelled and made himself "
                   "king of Yan."),
    "d30": dict(era="建武六年", era_en="Jianwu 6", t="平定关东", te="The east pacified", sh="定关东", she="East won",
                d="建武五年耿弇破张步于临淄，刘纡、彭宠、秦丰相继覆灭；六年董宪、李宪败死，关东悉平。窦融遣使奉书，河西归附。隗嚣遣子入侍后又反，称臣于公孙述；"
                  "卢芳在匈奴支持下据五原、朔方、云中、定襄、雁门五郡，称帝于九原。光武罢郡国都尉，省并四百余县。",
                de="In Jianwu 5 Geng Yan beat Zhang Bu at Linzi, and Liu Yu, Peng Chong and Qin Feng were destroyed one after another; in year 6 Dong Xian and Li "
                   "Xian fell, and the whole east was pacified. Dou Rong sent envoys with letters of submission, bringing Hexi over. Wei Xiao, having sent his "
                   "son to court, then turned against Han and declared himself Gongsun Shu's vassal; Lu Fang, backed by the Xiongnu, held the five commanderies of "
                   "Wuyuan, Shuofang, Yunzhong, Dingxiang and Yanmen and proclaimed himself emperor at Jiuyuan. Emperor Guangwu abolished the commanderies' "
                   "military commandants and merged away more than four hundred counties."),
    "d34": dict(era="建武十年", era_en="Jianwu 10", t="平陇右", te="Longyou pacified", sh="平陇右", she="Longyou",
                d="建武八年光武亲征隗嚣，窦融率河西兵会于高平，隗嚣走西城；九年隗嚣病饿而死，十年来歙、耿弇等攻落门，隗纯降，陇右平。",
                de="In Jianwu 8 the emperor took the field against Wei Xiao in person, Dou Rong joining him at Gaoping with the Hexi army, and Wei Xiao fled to "
                   "Xicheng; in year 9 he died of illness and hunger, and in year 10 Lai Xi, Geng Yan and others took Luomen, Wei Chun surrendered and Longyou "
                   "was pacified."),
    "d36": dict(era="建武十二年", era_en="Jianwu 12", t="平蜀·天下复一", te="Shu conquered · the realm reunited", sh="平蜀", she="Shu",
                d="建武十一年岑彭破荆门、虎牙，溯江入蜀，为刺客所杀；吴汉继之，十二年十一月攻成都，公孙述中创夜死，延岑以城降，成家亡。天下复归一统，"
                  "惟卢芳仍据北边五郡。窦融随即奉诏入朝，河西诸郡直属东汉。",
                de="In Jianwu 11 Cen Peng broke the Jingmen–Huya barrier and advanced up the Yangzi into Shu, where he was killed by an assassin; Wu Han took over, "
                   "and in the 11th month of year 12 attacked Chengdu; Gongsun Shu was wounded and died that night, Yan Cen surrendered the city and Chengjia "
                   "was finished. The realm was united again, except that Lu Fang still held the five northern commanderies. Dou Rong was then summoned to court, "
                   "and the Hexi commanderies passed to the Eastern Han."),
    "d43": dict(era="建武十九年", era_en="Jianwu 19", t="马援平交趾", te="Ma Yuan pacifies Jiaozhi", sh="平交趾", she="Jiaozhi",
                d="卢芳 40 年降汉，旋复入匈奴；北边屡遭匈奴、乌桓寇掠，39 年徙雁门、代、上谷吏民于居庸关以东。40 年交趾征侧、征贰姊妹起兵，九真、日南、合浦响应，"
                  "取六十五城；伏波将军马援 42 年南征，43 年斩征侧、征贰，立铜柱为汉界。莎车王贤称雄西域。",
                de="Lu Fang surrendered to Han in AD 40 but soon went back to the Xiongnu; the northern frontier suffered repeated Xiongnu and Wuhuan raids, and "
                   "in 39 the officials and people of Yanmen, Dai and Shanggu were moved east of the Juyong Pass. In 40 the sisters Trưng Trắc and Trưng Nhị "
                   "rose in Jiaozhi, joined by Jiuzhen, Rinan and Hepu, taking sixty-five towns; Ma Yuan, General Who Calms the Waves, marched south in 42 and in "
                   "43 beheaded both sisters, setting up bronze pillars to mark the Han frontier. King Xian of Yarkand dominated the Western Regions."),
    "d48": dict(era="建武二十四年", era_en="Jianwu 24", t="匈奴分南北", te="The Xiongnu split north and south", sh="分南北", she="North & south",
                d="匈奴连年旱蝗，人畜死耗大半，单于继立之争又起。建武二十四年，统领南边八部的日逐王比自立为呼韩邪单于，款五原塞称臣，是为南匈奴；"
                  "蒲奴单于据漠北，是为北匈奴。50 年南单于入居西河美稷，置使匈奴中郎将护之。49 年乌桓内附，居缘边诸郡。",
                de="Years of drought and locusts killed more than half the Xiongnu's people and herds, and the succession was disputed again. In Jianwu 24 Bi, "
                   "the Rizhu king who led the eight southern tribes, made himself chanyu as Huhanye and came to the Wuyuan frontier to declare himself a "
                   "vassal: these were the Southern Xiongnu, while the chanyu Punu held the north of the Gobi as the Northern Xiongnu. In 50 the southern "
                   "chanyu settled at Meiji in Xihe under a General of the Household Sent to the Xiongnu. The Wuhuan submitted in 49 and settled along the "
                   "frontier commanderies."),
    "d73": dict(era="永平十六年", era_en="Yongping 16", t="窦固出塞·班超使西域", te="Dou Gu beyond the frontier · Ban Chao in the west",
                sh="班超出使", she="Ban Chao",
                d="69 年哀牢王柳貌内属，置永昌郡，汉地西达伊洛瓦底江。永平十六年窦固、耿忠出酒泉，击北匈奴呼衍王于天山，追至蒲类海，取伊吾卢地，置宜禾都尉屯田；"
                  "窦固遣假司马班超以三十六人使西域，夜袭匈奴使者于鄯善，鄯善、于阗皆降。次年复置西域都护、戊己校尉。",
                de="In 69 King Liumao of Ailao submitted and Yongchang Commandery was set up, carrying Han territory west to the Irrawaddy. In Yongping 16 Dou Gu "
                   "and Geng Zhong set out from Jiuquan, beat the Huyan king of the Northern Xiongnu in the Tianshan, pursued him to Lake Pulei and took the "
                   "Yiwulu lands, where a Yihe commandant set up farming garrisons; Dou Gu sent his acting major Ban Chao with thirty-six men to the Western "
                   "Regions; Ban Chao fell on the Xiongnu envoys at Shanshan by night, and Shanshan and Khotan both submitted. The next year the Protector-General "
                   "and the Wu-Ji colonels were restored."),
    "d89": dict(era="永元元年", era_en="Yongyuan 1", t="勒石燕然", te="The inscription at Yanran", sh="勒石燕然", she="Yanran",
                d="北匈奴内乱饥疫，南单于请兵北伐。永元元年车骑将军窦宪、耿秉率汉军与南匈奴、羌胡骑出鸡鹿塞、满夷谷、稒阳塞，会于涿邪山，大破北单于于稽落山，"
                  "降者二十余万人。窦宪登燕然山，命中护军班固作铭刻石而还。班超仍孤守疏勒、于阗。",
                de="The Northern Xiongnu were torn by strife, famine and plague, and the southern chanyu asked for troops to attack them. In Yongyuan 1 the "
                   "General of Chariots and Cavalry Dou Xian and Geng Bing led Han troops with Southern Xiongnu, Qiang and Hu horsemen out by the Jilu frontier post, the Manyi Valley "
                   "and the Guyang frontier post, joined forces at Mount Zhuoye and crushed the northern chanyu at Mount Jiluo, more than 200,000 people "
                   "surrendering. Dou Xian climbed Mount Yanran and had his army protector Ban Gu compose an inscription carved on the rock before turning back. Ban Chao still "
                   "held out alone in Kashgar and Khotan."),
    "d91": dict(era="永元三年", era_en="Yongyuan 3", t="北匈奴西遁", te="The Northern Xiongnu flee west", sh="北匈奴遁", she="Xiongnu flee",
                d="永元二年窦宪遣兵复取伊吾；三年耿夔、任尚出居延塞，围北单于于金微山，大破之，北单于西走，不知所在。鲜卑转徙据其故地，匈奴余种十余万落皆自号鲜卑。"
                  "龟兹、姑墨、温宿皆降，以班超为西域都护，居龟兹它乾城。90 年贵霜副王谢率七万众攻班超，粮尽请和。",
                de="In Yongyuan 2 Dou Xian sent troops to retake Yiwu; in year 3 Geng Kui and Ren Shang came out by the Juyan frontier, surrounded the northern "
                   "chanyu at the Jinwei Mountains and routed him, and he fled west to no one knew where. The Xianbei moved into his old lands, and more than a "
                   "hundred thousand households of Xiongnu remnants called themselves Xianbei. Kucha, Gumo and Wensu all submitted, and Ban Chao was made "
                   "Protector-General, based at Tuoqian in Kucha. In 90 the Kushan viceroy Xie had attacked Ban Chao with 70,000 men but sued for peace when his "
                   "supplies ran out."),
    "d94": dict(era="永元六年", era_en="Yongyuan 6", t="西域内属", te="The Western Regions submit", sh="西域内属", she="West submits",
                d="永元六年秋班超发龟兹、鄯善等八国兵七万余人，讨焉耆、危须、尉犁，斩焉耆王广，传首京师，更立元孟。「于是西域五十余国悉皆纳质内属」，"
                  "东汉对西域的经营至于极盛。97 年班超遣甘英使大秦，抵条支海滨而还。（此节点原为汉末卷开篇）",
                de="In the autumn of Yongyuan 6 Ban Chao raised over 70,000 men from eight states including Kucha and Shanshan against Karasahr, Weixu and Yuli, "
                   "beheaded Guang, king of Karasahr, sent his head to the capital and set up Yuanmeng in his place. 'Thereupon more than fifty states of the "
                   "Western Regions all sent hostages and submitted': Eastern Han control of the Western Regions was at its height. In 97 Ban Chao sent Gan "
                   "Ying towards Da Qin; he reached the shore of the sea of Tiaozhi and turned back. (This snapshot used to open the Late Han and the Three Kingdoms volume.)"),
    "d107": dict(era="永初元年", era_en="Yongchu 1", t="罢西域都护·羌乱", te="The Protectorate abandoned · the Qiang war", sh="罢都护", she="Protectorate ends",
                 d="班超 102 年东归，继任都护任尚苛急失众，西域诸国反叛，围攻都护段禧。永初元年诏罢西域都护，迎还伊吾、柳中屯田吏士。同年征发羌骑赴西域，"
                   "羌众溃散，先零羌滇零在北地自称天子，寇掠三辅、断陇道，汉军屡败，凉州大乱；111 年陇西、安定、北地、上郡四郡内迁。",
                 de="Ban Chao went home in 102; his successor Ren Shang's harshness lost the states' loyalty, and they rose and besieged the Protector-General "
                    "Duan Xi. In Yongchu 1 an edict abolished the Protectorate and recalled the farming garrisons of Yiwu and Liuzhong. That year Qiang "
                    "horsemen conscripted for the Western Regions deserted; Dianlian of the Xianlian Qiang proclaimed himself Son of Heaven in Beidi, raided "
                    "the capital region and cut the road to Long, the Han armies were beaten again and again, and Liang Province fell into chaos; in 111 the "
                    "commanderies of Longxi, Anding, Beidi and Shang were moved inland."),
    "d127": dict(era="永建二年", era_en="Yongjian 2", t="班勇复通西域", te="Ban Yong reopens the west", sh="班勇", she="Ban Yong",
                 d="118 年先零羌平，凉州稍安。123 年以班超之子班勇为西域长史，屯柳中，124—126 年破车师前后部，逐北匈奴呼衍王，鄯善、龟兹、姑墨、温宿诸国皆服。"
                   "永建二年班勇与敦煌太守张朗讨焉耆，焉耆王元孟降，「于是龟兹、疏勒、于阗、莎车等十七国皆来服从」。",
                 de="The Xianlian Qiang were subdued in 118 and Liang Province grew quieter. In 123 Ban Chao's son Ban Yong was made Chief Clerk of the "
                    "Western Regions, garrisoned at Liuzhong; in 124–126 he broke the front and rear kingdoms of Jushi and drove off the Huyan king of the "
                    "Northern Xiongnu, and Shanshan, Kucha, Gumo and Wensu all submitted. In Yongjian 2 Ban Yong and Zhang Lang, Administrator of Dunhuang, "
                    "attacked Karasahr; its king Yuanmeng surrendered, 'and Kucha, Kashgar, Khotan, Yarkand and seventeen states in all came to submit'."),
    "d156": dict(era="永寿二年", era_en="Yongshou 2", t="檀石槐统一鲜卑", te="Tanshihuai unites the Xianbei", sh="檀石槐", she="Tanshihuai",
                 d="140—145 年羌乱再起，三辅、陇右残破。鲜卑檀石槐勇健有谋略，立庭于弹汗山歠仇水上，东西部大人皆归焉，南抄缘边，北拒丁零，东却夫余，西击乌孙，"
                   "「尽据匈奴故地，东西万四千余里」。永寿二年寇云中，此后连年入塞。166 年起党锢之祸，宦官专权。",
                 de="The Qiang rose again in 140–145, ravaging the capital region and Longyou. Tanshihuai of the Xianbei, brave and shrewd, set up his court on "
                    "the Chuochou River below Mount Danhan; the chiefs of east and west all came over to him, and he raided the frontier to the south, held off "
                    "the Dingling to the north, pushed back Buyeo to the east and struck at Wusun to the west, 'taking all the old Xiongnu lands, more than "
                    "fourteen thousand li from east to west'. In Yongshou 2 he raided Yunzhong and thereafter crossed the frontier year after year. From 166 "
                    "the Partisan Prohibitions began and the eunuchs held power."),
    "d169": dict(era="建宁二年", era_en="Jianning 2", t="段颎平东羌", te="Duan Jiong crushes the Eastern Qiang", sh="平东羌", she="E. Qiang",
                 d="159 年起西羌、东羌复叛。护羌校尉段颎主剿，前后百八十战，斩首三万八千余级；建宁二年于射虎谷大破东羌，东羌悉平。是年第二次党锢，李膺等百余人死狱中。",
                 de="The Western and Eastern Qiang rose again from 159. Duan Jiong, Protector of the Qiang, favoured extermination and in 180 engagements took "
                    "more than 38,000 heads; in Jianning 2 he crushed the Eastern Qiang at Shehu Valley and they were wholly subdued. That year saw the second "
                    "Partisan Prohibition, in which Li Ying and more than a hundred others died in prison."),
    "d177": dict(era="熹平六年", era_en="Xiping 6", t="三将出击鲜卑", te="Three generals strike the Xianbei", sh="击鲜卑", she="Xianbei war",
                 d="鲜卑连年寇边，幽、并、凉三州无岁不被其害。熹平六年八月遣夏育出高柳、田晏出云中、臧旻率南单于出雁门，各将万骑，三道出塞二千余里；"
                   "檀石槐命三部大人迎战，汉军大败，丧其节传辎重，各将数十骑奔还，死者十七八。",
                 de="The Xianbei raided the frontier every year, and You, Bing and Liang provinces suffered without respite. In the 8th month of Xiping 6 Xia Yu "
                    "set out from Gaoliu, Tian Yan from Yunzhong and Zang Min with the southern chanyu from Yanmen, each with ten thousand horsemen, three "
                    "columns striking more than two thousand li beyond the frontier; Tanshihuai sent the chiefs of his three divisions against them, and the "
                    "Han armies were routed, losing their credentials and baggage, each general fleeing back with a few dozen riders and seven or eight in ten "
                    "of the men killed."),
    "d184": dict(era="", era_en="", t="", te="", sh="", she="", d="", de=""),
}
